/* roomscroll-20261028a: HubFace Room Chat - thin see-through scrollbars; a jump button in the chat's top row appears only when the
   conversation overflows; it toggles Top (start of conversation + message box) <-> Back (where you were). Rollback: remove its script tag (index.html.bak-roomscroll-20261028) */
(function(){'use strict';if(window.__rbScr)return;window.__rbScr=1;
var st=document.createElement('style');st.textContent='#ui,#ui *{scrollbar-width:thin;scrollbar-color:rgba(160,180,220,.35) transparent}#ui ::-webkit-scrollbar{width:8px;height:8px}#ui ::-webkit-scrollbar-track{background:transparent}#ui ::-webkit-scrollbar-thumb{background:rgba(160,180,220,.3);border-radius:8px;border:2px solid transparent;background-clip:padding-box}#ui ::-webkit-scrollbar-thumb:hover{background-color:rgba(160,180,220,.55)}html[data-theme=light] #ui,html[data-theme=light] #ui *{scrollbar-color:rgba(60,80,120,.3) transparent}html[data-theme=light] #ui ::-webkit-scrollbar-thumb{background-color:rgba(60,80,120,.28)}#rbJmp[hidden]{display:none!important}#rbJmp{flex:0 0 auto;white-space:nowrap}';document.head.appendChild(st);
var mode='top',saved=0;
function C(){return document.getElementById('rb_roomChat')}
function paint(){var b=document.getElementById('rbJmp'),c=C();if(!b||!c)return;var top=c.scrollTop<4;if(mode==='back'&&!top){mode='top'}var hd=!(mode==='back'||!top),tx=mode==='top'?'\u2B06 Top':'\u2B07 Back';if(b.hidden!==hd)b.hidden=hd;if(b.textContent!==tx)b.textContent=tx;b.title=mode==='top'?'Jump to the start of the chat and the message box':'Back to where you were'}
function jump(){var c=C(),i=document.getElementById('rb_rcIn');if(!c)return;if(mode==='top'){saved=c.scrollTop;c.scrollTop=0;try{i&&i.focus({preventScroll:true})}catch(_){}mode='back';setTimeout(function(){mode='back';paint2()},0)}else{c.scrollTop=saved;mode='top'}paint2()}
function paint2(){var b=document.getElementById('rbJmp');if(!b)return;if(mode==='back'){if(b.hidden)b.hidden=false;if(b.textContent!=='\u2B07 Back')b.textContent='\u2B07 Back';b.title='Back to where you were'}else paint()}
function attach(){var i=document.getElementById('rb_rcIn'),c=C();if(!i||!c)return;var b=document.getElementById('rbJmp');if(b&&b.isConnected&&b.parentNode===i.parentNode)return;if(b)b.remove();b=document.createElement('button');b.type='button';b.id='rbJmp';var mic=document.getElementById('rb_rcMic');if(mic)b.className=mic.className.replace(/\braMic\b|\braOn\b|\bon\b/g,'').trim();b.hidden=true;b.addEventListener('mousedown',function(e){e.preventDefault()});b.addEventListener('click',jump);i.parentNode.appendChild(b);mode='top';c.addEventListener('scroll',function(){if(mode==='back'&&c.scrollTop<4)return;if(mode==='back')mode='top';paint()});paint()}
new MutationObserver(attach).observe(document.documentElement,{childList:true,subtree:true});setInterval(paint,1500);attach();})();
